'use strict';
// NEW v12.1: 17 species/races, six frames each, prepared once and shared by all instances.
const animatedCreatureOld={drawCreature,drawPerson,icon:makeControlIcon};
const creatureSheetDefs={
 human:{file:'people-light-v1.png',row:0,size:1.55},elf:{file:'people-light-v1.png',row:1,size:1.65},dwarf:{file:'people-light-v1.png',row:2,size:1.4},
 orc:{file:'people-dark-v1.png',row:0,size:1.85},goblin:{file:'people-dark-v1.png',row:1,size:1.4},beastkin:{file:'people-dark-v1.png',row:2,size:1.7},
 sheep:{file:'wildlife-animation-v1.png',row:0,size:1.55},wolf:{file:'wildlife-animation-v1.png',row:1,size:1.65},deer:{file:'wildlife-animation-v1.png',row:2,size:1.8},rabbit:{file:'wildlife-animation-v1.png',row:3,size:1},fox:{file:'wildlife-animation-v1.png',row:4,size:1.5},
 stego:{file:'dinosaurs-animation-v1.png',row:0,size:2.6},allosaur:{file:'dinosaurs-animation-v1.png',row:1,size:2.65},triceratops:{file:'dinosaurs-animation-v1.png',row:2,size:2.6},raptor:{file:'dinosaurs-animation-v1.png',row:3,size:2.05},mammoth:{file:'ice-animation-v1.png',row:0,size:3.1},saber:{file:'ice-animation-v1.png',row:1,size:2.1}
};
const creatureSheets=new Map();
function sheetSpecies(e){return e.kind==='human'?e.race||'human':e.species||e.kind;}
function prepareCreatureSheet(img,metadata){const cell=64,sheet=document.createElement('canvas');sheet.width=cell*6;sheet.height=cell*metadata.rows;const c=sheet.getContext('2d');c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';for(let row=0;row<metadata.rows;row++){const boxes=metadata.boxes.slice(row*6,row*6+6),scale=54/Math.max(...boxes.map(b=>Math.max(b[2]-b[0],b[3]-b[1])));for(let frame=0;frame<6;frame++){const [x,y,right,bottom]=boxes[frame],w=right-x,h=bottom-y;c.drawImage(img,x,y,w,h,frame*cell+(cell-w*scale)/2,row*cell+58-h*scale,w*scale,h*scale);}}return sheet;}
for(const [file,metadata] of Object.entries(animationSheetMetadata)){const img=new Image(),asset={img,ready:false,sheet:null,url:null,metadata};creatureSheets.set(file,asset);img.onload=()=>{try{asset.sheet=prepareCreatureSheet(img,metadata);asset.ready=true;mapDirty=true;if(tab==='life'||tab==='epochs')renderTools();}catch(error){console.warn('Không chuẩn bị được sprite sheet '+file,error);}};img.onerror=()=>console.warn('Không tải được sprite sheet '+file);img.src='assets/animation/'+file;}
function creatureFrame(e){const l=lifeFor(e),m=motionFor(e),v=Math.hypot(m.vx,m.vy);if(['sleep','rest'].includes(l.action)&&v<.12)return{frame:5,next:5,blend:0};if(v>.13){const phase=(m.steps*3.5)%2,frame=phase<1?1:2;return{frame,next:frame===1?2:1,blend:(phase%1)*.6};}if(e.kind==='human'){if(l.load>0||l.action==='carry')return{frame:4,next:4,blend:0};if(['chop','build','mine','plant','harvest','craft','fish'].includes(l.action)){const blend=(1-Math.cos(animationPose(e).phase))*.5;return{frame:0,next:3,blend};}}else{if(['graze','hunt'].includes(l.action))return{frame:3,next:3,blend:0};if(l.action==='flee')return{frame:4,next:4,blend:0};}return{frame:0,next:0,blend:0};}
function paintCreatureFrame(e,bob=0){const def=creatureSheetDefs[sheetSpecies(e)],asset=def&&creatureSheets.get(def.file);if(!asset?.ready)return false;const pose=creatureFrame(e),m=motionFor(e),juvenile=e.kind==='human'?e.age<16:(e.juvenileUntil>simTime||e.age<1),scale=juvenile?(e.kind==='human'?.68+Math.min(16,e.age)/16*.32:.65):1,size=def.size*scale,alpha=ctx.globalAlpha;ctx.save();ctx.translate(e.x,e.y+(pose.frame===5?0:bob));ctx.scale(m.facing<0?-1:1,1);ctx.imageSmoothingEnabled=true;const paint=(frame,opacity)=>{ctx.globalAlpha=alpha*opacity;ctx.drawImage(asset.sheet,frame*64,def.row*64,64,64,-size/2,-size*.72,size,size);};const cycle=walkCycleAssets.get(walkingSheetFile(def.file)),walk=walkingPose(e);if(walk.walking&&cycle?.ready){const segment=(sheet,frame,y,height)=>{ctx.globalAlpha=alpha;ctx.drawImage(sheet,frame*64,def.row*64+y,64,height,-size/2,-size*.72+y/64*size,size,height/64*size);};if(e.kind==='human'&&lifeFor(e).load>0){segment(asset.sheet,4,0,48);segment(cycle.sheet,walk.frame,48,16);}else segment(cycle.sheet,walk.frame,0,64);}else{const frame=pose.blend>.5?pose.next:pose.frame;paint(frame,1);}ctx.restore();return true;}
// Human work overlays are already embedded in the new frames; avoid drawing duplicate axes/log bundles.
drawCreature=function(e,bob){if(isResidentIndoors(e))return;if(!paintCreatureFrame(e,bob))animatedCreatureOld.drawCreature(e,bob);};
drawPerson=function(e,bob){if(!paintCreatureFrame(e,bob))animatedCreatureOld.drawPerson(e,bob);};
for(const key of Object.keys(creatureSheetDefs)){const toolKey=['human','elf','dwarf','orc','goblin','beastkin','sheep','wolf'].includes(key)?key:'ancient-'+key;iconCatalog[toolKey]={file:creatureSheetDefs[key].file,index:creatureSheetDefs[key].row*6,columns:6};}
makeControlIcon=function(key){const def=creatureSheetDefs[key.replace('ancient-','')],asset=def&&creatureSheets.get(def.file);if(!def)return animatedCreatureOld.icon(key);const span=document.createElement('span');span.className='item-picture atlas-picture';span.setAttribute('aria-hidden','true');if(!asset?.ready){span.textContent=key.startsWith('ancient-')?'🐾':'✦';return span;}try{asset.url??=asset.sheet.toDataURL();span.style.backgroundImage='url("'+asset.url+'")';span.style.backgroundSize='600% '+asset.metadata.rows*100+'%';span.style.backgroundPosition='0% '+(def.row/(asset.metadata.rows-1)*100)+'%';}catch{span.textContent=key.startsWith('ancient-')?'🐾':'✦';}return span;};
// MODIFIED: sort using actual new sprite footprint, including large ancient animals.
const sheetDepthItems=worldDepthItems;
worldDepthItems=function(...args){const items=sheetDepthItems(...args);for(const item of items)if(item.type==='creature'){const e=item.e,def=creatureSheetDefs[sheetSpecies(e)];if(def)item.depth=spriteGround(e.y,def.size*(e.kind==='human'&&e.age<16?.68+e.age/16*.32:e.kind!=='human'&&(e.juvenileUntil>simTime||e.age<1)?.65:1));}return items.sort((a,b)=>a.depth-b.depth);};
window.mamWorld={...window.mamWorld,getCreatureSheets:()=>Object.entries(creatureSheetDefs).map(([species,d])=>({species,frames:6,ready:!!creatureSheets.get(d.file)?.ready,file:d.file}))};
